package com.kylecorry.trail_sense.shared.dem

import androidx.test.platform.app.InstrumentationRegistry
import com.kylecorry.andromeda.files.AssetFileSystem
import com.kylecorry.sol.units.Coordinate

/**
 * Reference elevations from https://open-meteo.com (Copernicus DEM), generated by generate-dem-test-data.py in the
 * Earth Model project.
 *
 * ESA - EUsers, who, in their research, use the Copernicus DEM, are requested to use the following DOI when citing the data source in their publications:
 *
 * https://doi.org/10.5270/ESA-c5d3d65
 */
internal class DemTestData private constructor(
    // Random points in hiking areas by terrain (mountains, hills, flat), over the ocean, and well known peaks
    val points: Map<String, List<Pair<Coordinate, Float>>>,
    // Points every 300 meters along each route, in order
    val routes: Map<String, List<Pair<Coordinate, Float>>>,
    // Pairs of nearby points on either side of a tile boundary ("seam"), and pairs of the same size away from any
    // boundary to compare them to ("control")
    val seams: Map<String, List<Pair<Pair<Coordinate, Float>, Pair<Coordinate, Float>>>>
) {
    companion object {
        suspend fun load(): DemTestData {
            val assets = AssetFileSystem(InstrumentationRegistry.getInstrumentation().context)
            suspend fun rows(name: String): List<List<String>> {
                return assets.read("dem_tests/$name.csv").lines().drop(1).filter { it.isNotBlank() }
                    .map { it.split(",") }
            }

            fun point(row: List<String>, start: Int): Pair<Coordinate, Float> {
                return Coordinate(row[start].toDouble(), row[start + 1].toDouble()) to row[start + 2].toFloat()
            }

            return DemTestData(
                rows("points").groupBy({ it[0] }, { point(it, 1) }),
                rows("routes").groupBy({ it[0] }, { point(it, 1) }),
                rows("seams").groupBy({ it[0] }, { point(it, 1) to point(it, 4) })
            )
        }
    }
}
